  return hexkl_mm_u8i4_moe_layer_run(
    env->tbl, env->vtcm_base, env->vtcm_size, env->config_off, 1u, op->K, op->N,
    op->N_out, op->n_experts, h, h + op->n_experts, idx, cnt, w, in, out,
    env->pool, env->scratch, env->moe_flags | extra);
}

uint32_t i;
