#define HEXKL_DMA_RING_N 256u

static hexkl_dma_desc2d g_ring[HEXKL_DMA_RING_N] __attribute__((aligned(128)));
static uint32_t g_push, g_pop;
static hexkl_dma_desc2d *g_tail;
static int g_started;

int hexkl_dma_ring_try_reset(void) {
  const uint32_t last = (g_push - 1u) & (HEXKL_DMA_RING_N - 1u);
  if (g_tail == NULL || g_tail != &g_ring[last] || g_tail->desc_size != 1u ||
      g_tail->desc_type != 9u || !hexkl_dma_ring_is_done(last)) {
    return 0;
  }
  g_push = 0;
  g_pop = 0;
  g_tail = NULL;
  g_started = 0;
  return 1;
}

